using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and fundamental forces." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and civilizations." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen has over 15 years of experience in software engineering and distributed systems. She holds a Ph.D. from MIT and has published extensively on cloud computing architectures.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Mathematics", Bio = "Dr. Martinez specializes in applied mathematics and statistics. His research focuses on mathematical modeling of complex systems. He received his Ph.D. from Stanford University.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Prof. Sarah Johnson", Title = "Professor of English", Bio = "Prof. Johnson is an acclaimed author and literary critic with expertise in modern American literature. She has won multiple teaching excellence awards.", Email = "sjohnson@university.edu" },
            new() { Id = 4, Name = "Dr. James Park", Title = "Associate Professor of Physics", Bio = "Dr. Park conducts research in quantum mechanics and particle physics. He previously worked at CERN and has contributed to several landmark discoveries.", Email = "jpark@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Brooks", Title = "Professor of History", Bio = "Dr. Brooks is a historian specializing in medieval European history. She has authored three books and leads the university's historical research initiative.", Email = "ebrooks@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Torres", Title = "Assistant Professor of Computer Science", Bio = "Dr. Torres focuses on artificial intelligence and machine learning. He spent five years in industry at leading tech companies before joining academia.", Email = "mtorres@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques. Prerequisites: CS101.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Code = "CS301", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, machine learning, neural networks, and natural language processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, InstructorId = 6, IsFeatured = true },
            new() { Id = 4, Code = "MATH101", Title = "Calculus I", Description = "Introduction to differential calculus covering limits, derivatives, and applications. Suitable for students in science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, InstructorId = 2 },
            new() { Id = 5, Code = "MATH201", Title = "Linear Algebra", Description = "Study of vector spaces, matrices, linear transformations, and eigenvalues. Essential for advanced mathematics and computer science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, InstructorId = 2, IsFeatured = true },
            new() { Id = 6, Code = "ENG101", Title = "Composition and Rhetoric", Description = "Develop critical thinking and writing skills through essay composition, argumentation, and rhetorical analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 3, InstructorId = 3 },
            new() { Id = 7, Code = "ENG250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, examining major authors and literary movements.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 8, Code = "PHYS101", Title = "General Physics I", Description = "Introduction to mechanics, thermodynamics, and waves. Includes weekly laboratory sessions. Co-requisite: MATH101.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Lab Fri 1:00–3:00 PM", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 9, Code = "PHYS301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave functions, the Schrödinger equation, and quantum measurement.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 10, Code = "HIST101", Title = "World History to 1500", Description = "Survey of world civilizations from ancient times through the late medieval period, covering political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, InstructorId = 5, IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public Department? GetDepartmentForCourse(int courseId)
    {
        var course = GetCourse(courseId);
        return course != null ? GetDepartment(course.DepartmentId) : null;
    }
}

