                            <p class="card-text">@instructor.Bio</p>
                            <p class="card-text"><small class="text-muted">@instructor.Email</small></p>
                        </div>
                    </div>
                }

                <div class="mt-3">
                    <a href="/enroll" class="btn btn-primary w-100">Request Enrollment</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;
    private Department? department;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
        if (course is not null)
        {
            department = Catalog.GetDepartment(course.DepartmentId);
            instructor = Catalog.GetInstructor(course.InstructorId);
        }
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@rendermode InteractiveServer

<PageTitle>Browse Courses</PageTitle>

<div class="container">
    <h1 class="mb-4">Browse Courses</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search by title, code, or keyword..."
                   @bind="searchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="selectedDepartmentId">
                <option value="0">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-secondary w-100" @onclick="ClearFilters">Clear</button>
        </div>
    </div>

    @if (filteredCourses.Any())
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Schedule</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in filteredCourses)
                    {
                        var dept = Catalog.GetDepartment(course.DepartmentId);
                        <tr>
                            <td><strong>@course.Code</strong></td>
                            <td>@course.Title</td>
                            <td>@dept?.Name</td>
                            <td>@course.Credits</td>
                            <td>@course.Schedule</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @filteredCourses.Count course(s)</p>
    }
    else
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    private string _searchTerm = string.Empty;
    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int _selectedDepartmentId;
    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; ApplyFilters(); }
    }

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        if (DepartmentId.HasValue)
        {
            _selectedDepartmentId = DepartmentId.Value;
        }
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = Catalog.SearchCourses(
            string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm,
            _selectedDepartmentId > 0 ? _selectedDepartmentId : null);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartmentId = 0;
        ApplyFilters();
    }
}

