toolArgs.file_text:
@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@rendermode InteractiveServer

<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1 class="mb-4">Enrollment Request</h1>
    <p class="text-muted">Submit your enrollment request below. You will receive a confirmation from the registrar's office.</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted Successfully</h4>
            <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for
                <strong>@selectedCourseName</strong> has been received.</p>
            <p>Student ID: @model.StudentId</p>
            <a href="/courses" class="btn btn-primary">Browse More Courses</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-8">
                <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
                        <ValidationMessage For="() => model.StudentName" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="model.StudentId"
                                   placeholder="e.g., CS123456" />
                        <ValidationMessage For="() => model.StudentId" class="text-danger" />
                        <div class="form-text">Format: 2 uppercase letters followed by 6 digits.</div>
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" class="form-select" @bind-Value="model.CourseId">
                            <option value="0">— Select a course —</option>
                            @foreach (var course in courses)
                            {
                                <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => model.CourseId" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    private EnrollmentRequest model = new();
    private List<Course> courses = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(model.CourseId);
        selectedCourseName = course is not null ? $"{course.Code} — {course.Title}" : "Unknown";
        submitted = true;
    }

    private void Reset()
    {
        model = new EnrollmentRequest();
        submitted = false;
        selectedCourseName = string.Empty;
    }
}
